UPDATE public.study_materials SET
body_md=body_md || E'\n\n### Exemplo resolvido: porcentagens sucessivas\n\nUm produto de R$ 100 recebe aumento de 20% e depois desconto de 20%. Após o aumento custa R$ 120; após o desconto, R$ 96. O resultado é redução líquida de 4%, pois 1,20×0,80=0,96.\n\n### Exemplo resolvido: regra de três inversa\n\nSe 4 trabalhadores concluem um serviço em 6 dias, 8 trabalhadores de mesma produtividade terminam em 3 dias: 4×6=8×3.\n\n### Exemplo resolvido: frações\n\nPara somar 1/3+1/4, use MMC(3,4)=12: 4/12+3/12=7/12.\n\n**Dica de prova:** compare se a relação é direta ou inversa antes de montar a proporção; não some percentuais de bases diferentes.',
quiz='[{"q":"Um produto de R$ 100 com aumento de 20% e desconto posterior de 20% passa a custar R$ 96.","a":true,"why":"Correto. 100×1,20×0,80=96. Percentuais sucessivos são multiplicados, não anulados."},{"q":"A soma de 1/3 com 1/4 é igual a 2/7.","a":false,"why":"Errado. O denominador comum é 12: 1/3+1/4=4/12+3/12=7/12."}]'::jsonb,
practice_review=jsonb_set(practice_review,'{full_material_audit}',jsonb_build_object('status','expanded_pending_independent_review','checked_at','2026-11-21','quiz_count',2)),updated_at=now()
WHERE slug='rlm-acervo-matematica-basica' AND quiz->0->>'q' LIKE 'O material Números Reais.pdf%';
UPDATE public.study_materials SET
body_md=body_md || E'\n\n## 9. Exemplo numérico para fixação\n\nSuponha que, em um mês, o empregado adquira direito a R$ 200 de férias, já incluído o adicional de um terço para simplificar o exemplo, sem considerar encargos. A empresa registra débito em despesa de férias de R$ 200 e crédito em obrigação de férias a pagar de R$ 200. Quando essa obrigação for quitada, debita-se a obrigação e credita-se caixa/bancos, sem reconhecer novamente os mesmos R$ 200 como despesa.\n\n**Dica de prova:** identifique o momento do fato gerador (serviço prestado) e separe-o da data do pagamento.',
quiz='[{"q":"Pelo regime de competência, a despesa de férias deve ser reconhecida à medida que o empregado presta serviços e adquire o direito, mesmo antes do pagamento.","a":true,"why":"Correto. O trabalho prestado gera despesa e obrigação no período de competência. O pagamento posterior liquida o passivo."},{"q":"Ao pagar férias já integralmente reconhecidas como obrigação, a empresa deve registrar novamente toda a despesa de férias.","a":false,"why":"Errado. Isso duplicaria a despesa. Na liquidação, baixa-se a obrigação contra caixa/bancos, ressalvados ajustes e encargos aplicáveis."}]'::jsonb,
practice_review=jsonb_set(coalesce(practice_review,'{}'::jsonb),'{full_material_audit}',jsonb_build_object('status','expanded_pending_independent_review','checked_at','2026-11-21','quiz_count',2)),updated_at=now()
WHERE slug='contabilidade-provisao-ferias-regime-competencia' AND jsonb_array_length(quiz)=0;